-- public.ai_actions
ALTER TABLE public.ai_actions ENABLE ROW LEVEL SECURITY                                                           ;
CREATE POLICY "ai_actions: own sessions" ON public.ai_actions AS PERMISSIVE FOR ALL TO public
USING ((session_id IN ( SELECT ai_agent_sessions.id
FROM ai_agent_sessions
WHERE (ai_agent_sessions.user_id = (auth.uid())::text))));

-- public.ai_agent_sessions
ALTER TABLE public.ai_agent_sessions ENABLE ROW LEVEL SECURITY                                                    ;
CREATE POLICY "ai_sessions: own" ON public.ai_agent_sessions AS PERMISSIVE FOR ALL TO public
USING ((user_id = (auth.uid())::text));

